5	namespace WPMedia\BackWPup\Admin\Rating;
6	
7	/**
8	 * Decides whether the rating notice should be displayed for a user.
9	 */
10	class RatingNoticeDecider {
11	
12		/**
13		 * Whether the current installation is PRO.
14		 *
15		 * @var bool
16		 */
17		private bool $is_pro;
18	
19		/**
20		 * Constructor.
21		 *
22		 * @param bool $is_pro Pass true when running under BackWPup PRO.
23		 */
24		public function __construct( bool $is_pro = false ) {
25			$this->is_pro = $is_pro;
26		}
27	
28		public const OPT_INSTALL_TYPE             = 'backwpup_install_type';     // 'new' | 'update' (set via RatingInstallStateInitializer).
29		public const OPT_INSTALL_TIME             = 'backwpup_first_install_ts'; // int timestamp.
30		public const META_DISMISSED               = 'backwpup_rating_notice_dismissed'; // bool.
31		public const META_DISMISSED_UNTIL         = 'backwpup_rating_notice_dismissed_until'; // int timestamp.
32		public const META_SHOWN                   = 'backwpup_rating_notice_shown';     // bool.
33		public const META_REMIND_AT               = 'backwpup_rating_notice_remind_at'; // int timestamp.
34		public const STATE_DISMISSED              = 'dismissed';
35		public const STATE_HAS_REMIND_AT          = 'has_remind_at';
36		public const STATE_REMIND_DUE             = 'remind_due';
37		public const STATE_DISMISSED_UNTIL_ACTIVE = 'dismissed_until_active';
38		public const STATE_DISMISSED_UNTIL_DUE    = 'dismissed_until_due';
39	
40		/**
41		 * Gets rating notice state for a user.
42		 *
43		 * @param int $user_id User ID.
44		 * @param int $now     Current timestamp.
45		 * @return array<string, bool>
46		 */
47		public function get_user_notice_state( int $user_id, int $now ): array {
48			$dismissed           = (bool) get_user_meta( $user_id, self::META_DISMISSED, true );
49			$remind_at           = (int) get_user_meta( $user_id, self::META_REMIND_AT, true );
50			$dismissed_until     = (int) get_user_meta( $user_id, self::META_DISMISSED_UNTIL, true );
51			$has_remind_at       = 0 < $remind_at;
52			$has_dismissed_until = 0 < $dismissed_until;
53	
54			return [
55				self::STATE_DISMISSED              => $dismissed,
56				self::STATE_HAS_REMIND_AT          => $has_remind_at,
57				self::STATE_REMIND_DUE             => $has_remind_at && $remind_at <= $now,
58				self::STATE_DISMISSED_UNTIL_ACTIVE => $has_dismissed_until && $now < $dismissed_until,
59				self::STATE_DISMISSED_UNTIL_DUE    => $has_dismissed_until && $dismissed_until <= $now,
60			];
61		}
62	
63		/**
64		 * Whether the notice should be shown for the user.
65		 *
66		 * @param int $user_id User ID.
67		 * @param int $now     Current timestamp.
68		 */
69		public function should_show_for_user( int $user_id, int $now ): bool {
70			// Only new installations.
71			if ( 'new' !== (string) get_option( self::OPT_INSTALL_TYPE, '' ) ) {
72				return false;
73			}
74	
75			$install_ts = (int) get_option( self::OPT_INSTALL_TIME, 0 );
76			if ( 0 >= $install_ts ) {
77				return false;
78			}
79	
80			$state = $this->get_user_notice_state( $user_id, $now );
81	
82			if ( $state[ self::STATE_DISMISSED ] ) {
83				return false;
84			}
85	
86			if ( $state[ self::STATE_DISMISSED_UNTIL_ACTIVE ] ) {
87				return false;
88			}
89	
90			// Suppress the review banner while the Upgrade-to-PRO notice exposure window is still active.
91			if ( ! $this->is_pro && $this->is_upgrade_nudge_lifecycle_active( $user_id ) ) {
92				return false;
93			}
94	
95			if ( $state[ self::STATE_HAS_REMIND_AT ] ) {
96				return $state[ self::STATE_REMIND_DUE ];
97			}
98	
99			$shown = (bool) get_user_meta( $user_id, self::META_SHOWN, true );
100			if ( $shown ) {
101				return false;
102			}
103	
104			return true;
105		}
106	
107		/**
108		 * Marks notice as shown.
109		 *
110		 * @param int $user_id User ID.
111		 */
112		public function mark_shown( int $user_id ): void {
113			update_user_meta( $user_id, self::META_SHOWN, 1 );
114	
115			// Clear remind flag once the notice has been shown again.
116			delete_user_meta( $user_id, self::META_REMIND_AT );
117		}
118	
119		/**
120		 * Dismisses notice permanently.
121		 *
122		 * @param int $user_id User ID.
123		 */
124		public function dismiss_forever( int $user_id ): void {
125			update_user_meta( $user_id, self::META_DISMISSED, 1 );
126			update_user_meta( $user_id, self::META_DISMISSED_UNTIL, PHP_INT_MAX );
127			delete_user_meta( $user_id, self::META_REMIND_AT );
128		}
129	
130		/**
131		 * Dismisses notice until a given timestamp.
132		 *
133		 * @param int $user_id        User ID.
134		 * @param int $dismiss_until  Timestamp until which the notice is dismissed.
135		 */
136		public function dismiss_until( int $user_id, int $dismiss_until ): void {
137			if ( 0 >= $dismiss_until ) {
138				return;
139			}
140	
141			update_user_meta( $user_id, self::META_DISMISSED_UNTIL, $dismiss_until );
142	
143			// Clear remind + shown to allow the notice to reappear after the dismiss window.
144			delete_user_meta( $user_id, self::META_REMIND_AT );
145			delete_user_meta( $user_id, self::META_SHOWN );
146		}
147	
148		/**
149		 * Returns true while the Upgrade-to-PRO notice exposure window is still active for the user.
150		 *
151		 * The window ends when the notice has been permanently dismissed (sitewide or per-user)
152		 * or the per-user impression cap has been reached. Temporary ("for now") dismissals do
153		 * not end the lifecycle — the nudge will reappear once the dismissal expires.
154		 *
155		 * @param int $user_id WordPress user ID.
156		 * @return bool
157		 */
158		private function is_upgrade_nudge_lifecycle_active( int $user_id ): bool {
159			$dismiss_option = \WPMedia\BackWPup\Admin\Notices\Notices\NoticeUpgradeToPro::DISMISSED_SITE_OPTION_KEY;
160	
161			// Sitewide permanent dismiss.
162			if ( get_site_option( $dismiss_option ) ) {
163				return false;
164			}
165	
166			// Per-user permanent dismiss.
167			if ( get_user_option( $dismiss_option, $user_id ) ) {
168				return false;
169			}
170	
171			$sessions_shown = (int) get_user_meta(
172				$user_id,
173				\WPMedia\BackWPup\Admin\Notices\Notices\NoticeUpgradeToPro::SESSIONS_SHOWN_META_KEY,
174				true
175			);
176	
177			return $sessions_shown < \WPMedia\BackWPup\Admin\Notices\Notices\NoticeUpgradeToPro::NUMBER_OF_SESSIONS_BEFORE_CAP;
178		}
179	
180		/**
181		 * Sets remind timestamp.
182		 *
183		 * @param int $user_id User ID.
184		 * @param int $remind_at Timestamp for the next reminder.
185		 */
186		public function remind_later( int $user_id, int $remind_at ): void {
187			if ( 0 >= $remind_at ) {
188				return;
189			}
190	
191			update_user_meta( $user_id, self::META_REMIND_AT, $remind_at );
192		}
193	}
