3	namespace WPMedia\BackWPup\Admin\Notices\Notices;
4	
5	use BackWPup;
6	use Inpsyde\BackWPup\Notice\NoticeMessage;
7	use Inpsyde\BackWPup\Notice\DismissibleNoticeOption;
8	use Inpsyde\BackWPup\Notice\NoticeView;
9	
10	/**
11	 * Notice to encourage users to upgrade to Pro after a successful backup scheduled job run. This notice is dismissible and will be shown a maximum of 5 times per user, with a limit of one impression per day.
12	 */
13	class NoticeUpgradeToPro extends AbstractNotice {
14	
15		public const SESSIONS_SHOWN_META_KEY       = 'backwpup_upgrade_to_pro_sessions_shown';
16		public const LAST_SESSION_META_KEY         = 'backwpup_upgrade_to_pro_last_session';
17		public const NUMBER_OF_SESSIONS_BEFORE_CAP = 5;
18	
19		/**
20		 * The unique ID for this notice.
21		 */
22		public const ID = 'notice_upgrade_to_pro';
23	
24		/**
25		 * The site-option key used to record a permanent sitewide dismissal of this notice
26		 * (DismissibleNoticeOption::OPTION_PREFIX . self::ID).
27		 */
28		public const DISMISSED_SITE_OPTION_KEY = 'backwpup_dinotopt_notice_upgrade_to_pro';
29	
30	
31		/**
32		 * Constructor.
33		 *
34		 * @param NoticeView $view The view renderer for the notice.
35		 */
36		public function __construct( NoticeView $view ) {
37			parent::__construct( $view, true );
38		}
39	
40		/**
41		 * Determine if the notice should be displayed.
42		 *
43		 * @return bool
44		 */
45		protected function should_display(): bool {
46			// Never show if the user is in onboarding, is already Pro, or if the parent conditions for display are not met.
47			$onboarding_to_do = get_site_option( 'backwpup_onboarding', false );
48			if ( $onboarding_to_do || BackWPup::is_pro() || ! parent::should_display() ) {
49				return false;
50			}
51	
52			$user_id = get_current_user_id();
53			if ( ! $user_id ) {
54				return false;
55			}
56	
57			// Limit to 5 impressions per user
58			$sessions_shown = (int) get_user_meta( $user_id, self::SESSIONS_SHOWN_META_KEY, true );
59			if ( $sessions_shown >= self::NUMBER_OF_SESSIONS_BEFORE_CAP ) {
60				return false;
61			}
62	
63			// Show once per session (1 session = 1 day)
64			$last_session    = get_user_meta( $user_id, self::LAST_SESSION_META_KEY, true );
65			$current_session = gmdate( 'Y-m-d' ); // 1 session = 1 day
66			if ( $last_session === $current_session ) {
67				return false;
68			}
69	
70			// Record the impression for the user
71			update_user_meta( $user_id, self::SESSIONS_SHOWN_META_KEY, $sessions_shown + 1 );
72			update_user_meta( $user_id, self::LAST_SESSION_META_KEY, $current_session );
73	
74			return true;
75		}
76	
77		/**
78		 * Render the notice using the view.
79		 *
80		 * @param NoticeMessage $message
81		 */
82		protected function render( NoticeMessage $message ): void {
83			$this->view->banner( $message, null );
84		}
85	
86		/**
87		 * Get the dismiss action URL for the notice.
88		 *
89		 * @return string|null
90		 */
91		protected function get_dismiss_action_url(): ?string {
92			if ( ! $this->dismissible ) {
93				return null;
94			}
95	
96			return DismissibleNoticeOption::dismiss_action_url(
97				self::ID,
98				DismissibleNoticeOption::FOR_USER_FOR_GOOD_ACTION
99			);
100		}
101	
102		/**
103		 * Build the message for the notice.
104		 *
105		 * @return NoticeMessage
106		 */
107		protected function message(): NoticeMessage {
108			$notice_message             = new NoticeMessage( self::ID );
109			$notice_message->dismissurl = $this->get_dismiss_action_url();
110			return $notice_message;
111		}
112	
113		/**
114		 * Check if the current screen is allowed for this notice.
115		 *
116		 * @return bool
117		 */
118		protected function is_screen_allowed(): bool {
119			$screen = get_current_screen();
120			if ( ! $screen instanceof \WP_Screen || ! isset( $screen->id ) ) {
121				return false;
122			}
123			// Do not show on the first backup progress page.
124			if ( 'admin_page_backwpupfirstbackup' === $screen->id ) {
125				return false;
126			}
127			// Check if the current screen is a BackWPup page.
128			return isset( $screen->id ) && strpos( $screen->id, 'backwpup' ) !== false;
129		}
130	}
