33		/**
34		 * Allowed admin page IDs for displaying notices.
35		 *
36		 * @var array
37		 */
38		protected static $main_admin_page_ids = [
39			'toplevel_page_backwpup',
40			'toplevel_page_backwpup-network',
41		];
42	
43		/**
44		 * Initialize the notice, registering dismiss actions if needed.
45		 *
46		 * @return void
47		 */
48		protected function init(): void {
49			if ( ! $this->dismissible ) {
50				return;
51			}
52			// Register dismiss actions for this notice (per-user, not sitewide by default).
53			DismissibleNoticeOption::setup_actions( false, static::ID, 'read' );
54		}
55	
56		/**
57		 * Constructor.
58		 *
59		 * @param NoticeView $view The view renderer for the notice.
60		 * @param bool       $dismissible Whether the notice is dismissible.
61		 */
62		public function __construct( NoticeView $view, bool $dismissible = true ) {
63			$this->view        = $view;
64			$this->dismissible = $dismissible;
65			$this->init();
66		}
67	
68		/**
69		 * Returns whether the current screen should show the notice.
70		 *
71		 * @return bool
72		 */
73		protected function is_screen_allowed(): bool {
74			$screen = get_current_screen();
75			if ( ! $screen instanceof \WP_Screen ) {
76				return false;
77			}
78			return in_array( $screen->id, static::$main_admin_page_ids, true );
